const webhookBody = $('Webhook').item.json.body || {};
const currentMsgId = webhookBody.id;
const conversation = webhookBody.conversation || {};
const account = webhookBody.account || {};
const channel = conversation.channel || '';

const payload = $input.item.json.payload || [];

// Check if any newer incoming message exists (newer webhook execution will handle batch)
const newerIncoming = payload.filter(m => m.message_type === 0 && m.id > currentMsgId);
if (newerIncoming.length > 0) {
  return [];
}

// Find timestamp of last outgoing bot message
let lastOutgoingTime = 0;
for (const m of payload) {
  if (m.message_type === 1 && m.created_at > lastOutgoingTime) {
    lastOutgoingTime = m.created_at;
  }
}

// Collect all unreplied incoming messages
const unreplied = payload.filter(m => m.message_type === 0 && m.created_at >= lastOutgoingTime);

let consolidatedText = '';
if (unreplied.length > 0) {
  consolidatedText = unreplied.map(m => m.content).filter(Boolean).join('\n');
} else {
  consolidatedText = webhookBody.content || '';
}

return {
  json: {
    conversation_id: conversation.id,
    account_id: account.id,
    channel: channel,
    message: consolidatedText
  }
};

// 1. Obtener la respuesta de la IA
const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json.response || "";

// 2. Extraer datos del mensaje y canal
const webhookData = $("Webhook").item.json.body || {};
const conversation = webhookData.conversation || {};
const account = webhookData.account || {};
const channel = conversation.channel || "";

let formattedText = aiResponse;

// 3. Formatear según canal (Meta / WhatsApp vs Telegram)
if (channel.includes("Whatsapp") || channel.includes("Facebook") || channel.includes("Instagram")) {
  formattedText = formattedText.replace(/\*\*(.*?)\*\*/g, '*$1*');
  formattedText = formattedText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');
}

return {
  json: {
    content: formattedText,
    conversation_id: conversation.id,
    account_id: account.id,
    channel: channel
  }
};
